const price = Inputs.price || '';
const qty = Inputs.qty || 0;

// pull off the leading currency symbol (any non-digit run) and parse the number
const match = price.match(/^([^\d-]*)([\d,]*\.?\d*)$/);
const symbol = match ? match[1] : '';
const unitAmount = match ? parseFloat(match[2].replace(/,/g, '')) || 0 : 0;
const total = unitAmount * qty;

const fmt = (n) => n.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});

Outputs.line = `${qty} x ${symbol}${fmt(unitAmount)} = ${symbol}${fmt(total)}`;

